'use strict';
const $=id=>document.getElementById(id), screen=$('screen'), page=$('page'), rail=$('rail'), drawer=$('drawer'), quick=$('quick'), shade=$('shade'), reveal=$('reveal');
const apps={home:'Home',spotify:'Spotify',weather:'Weather',glucose:'Glucose',settings:'Settings',calendar:'Calendar',system:'System Information'};
const icons={home:'<path d="M3 10 12 3l9 7v10h-6v-7H9v7H3z"/>',spotify:'<circle cx="12" cy="12" r="10"/><path d="M6 9q6-3 12 1M7 13q5-2 10 1M8 16q4-1 8 1"/>',weather:'<path d="M6 19a5 5 0 0 1-1-10 7 7 0 0 1 13 1 4.5 4.5 0 0 1 0 9z"/>',glucose:'<path d="M12 2C8 8 4 12 4 16a8 8 0 0 0 16 0c0-4-4-8-8-14z"/>',settings:'<circle cx="12" cy="12" r="8"/><circle cx="12" cy="12" r="3"/><path d="M12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M7 2v6M17 2v6M7 14h3M14 14h3M7 18h3"/>',system:'<rect x="2" y="4" width="20" height="14" rx="2"/><path d="M8 22h8M12 18v4M5 11h4l2-4 3 8 2-4h3"/>',apps:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>'};
const icon=id=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+icons[id]+'</svg>';
const defaults=()=>({theme:'graphite',railStyle:'floating',opacity:100,delay:10,animation:'slide',speed:180,brightness:100,night:'off',autoHide:{home:true,spotify:true,weather:true,glucose:true,settings:false,calendar:true,system:true}});
const key='echo-show-preview-prefs-v1';let prefs=defaults(),active='home',category='navigation',expanded=true,timer,overlay=null,gesture=null;
try{const p=JSON.parse(localStorage.getItem(key)||'null');if(p&&typeof p==='object'){for(const [k,allowed] of Object.entries({theme:['graphite','black'],railStyle:['floating','transparent','edge'],animation:['none','fade','slide'],night:['off','manual','scheduled']}))if(allowed.includes(p[k]))prefs[k]=p[k];for(const [k,min,max] of [['opacity',25,100],['delay',5,60],['speed',100,350],['brightness',10,100]])if(Number.isFinite(p[k])&&p[k]>=min&&p[k]<=max)prefs[k]=p[k];for(const id of Object.keys(apps))if(typeof p.autoHide?.[id]==='boolean')prefs.autoHide[id]=p.autoHide[id]}}catch{}
function apply(){screen.dataset.theme=prefs.theme;screen.dataset.rail=prefs.railStyle;screen.dataset.animation=prefs.animation;screen.style.setProperty('--rail-opacity',prefs.opacity/100);screen.style.setProperty('--speed',prefs.speed+'ms');$('dim').style.opacity=String(Math.max((100-prefs.brightness)/100*.75,prefs.night==='manual'?.55:0));}
function save(){try{localStorage.setItem(key,JSON.stringify(prefs))}catch{}apply();schedule()}
function schedule(){clearTimeout(timer);if(expanded&&!overlay&&prefs.autoHide[active]&&!rail.contains(document.activeElement))timer=setTimeout(()=>setRail(false),prefs.delay*1000)}
function setRail(value){expanded=value;screen.classList.toggle('expanded',value);rail.inert=!value;rail.setAttribute('aria-hidden',String(!value));reveal.hidden=value;schedule()}
function renderRail(){rail.innerHTML=['home','spotify','weather','glucose'].map(id=>'<button data-page="'+id+'" aria-label="'+apps[id]+'" '+(active===id?'aria-current="page"':'')+'>'+icon(id)+'</button>').join('')+'<button data-open="drawer" aria-label="Apps" aria-expanded="'+(overlay==='drawer')+'">'+icon('apps')+'</button>'}
function clock(){if(active!=='home')return;const now=new Date();$('clock').textContent=new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:false}).format(now);$('date').textContent=new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long'}).format(now)}
function renderPage(){screen.dataset.page=active;renderRail();if(active==='home'){page.innerHTML='<div class="home"><div id="clock" class="clock"></div><div id="date" class="date"></div></div><div class="tiles"><button class="tile" data-page="weather"><span>Weather · Bournemouth</span><strong>10° · Cloudy</strong></button><button class="tile" data-page="spotify"><span>Spotify</span><strong>Example track</strong></button><button class="tile" data-page="glucose"><span>Glucose · sample</span><strong>6.2 →</strong></button></div>';clock()}else if(active==='settings'){renderSettings()}else{page.innerHTML='<div class="placeholder"><h1>'+apps[active]+'</h1><p>This page is planned for a later prototype increment. No live service is connected.</p><button data-page="home">Return Home</button></div>'}}
function navigate(id){if(!Object.hasOwnProperty.call(apps,id))return;closeOverlay(false);active=id;renderPage();setRail(true)}
function closeOverlay(restore=true){const previous=overlay;overlay=null;drawer.hidden=true;quick.hidden=true;shade.hidden=true;renderRail();if(restore){if(previous==='quick')$('quickHandle').focus();else rail.querySelector('[data-open=drawer]')?.focus()}schedule()}
function openOverlay(id){overlay=id;clearTimeout(timer);shade.hidden=false;drawer.hidden=id!=='drawer';quick.hidden=id!=='quick';if(id==='drawer'){setRail(true);drawer.innerHTML='<header>Apps<button data-close aria-label="Close Apps">×</button></header><div class="app-grid">'+['settings','calendar','system'].map(a=>'<button data-page="'+a+'">'+icon(a)+apps[a]+(a==='settings'?'':'<small>Planned</small>')+'</button>').join('')+'</div>'}else{renderQuick()}renderRail();(id==='drawer'?drawer:quick).querySelector('[data-close]')?.focus()}
function selectRow(label,k,options){return '<div class="setting"><label>'+label+'</label><select aria-label="'+label+'" data-pref="'+k+'">'+options.map(([v,t])=>'<option value="'+v+'" '+(String(prefs[k])===String(v)?'selected':'')+'>'+t+'</option>').join('')+'</select></div>'}
function rangeRow(label,k,min,max,step,suffix,note=''){return '<div class="setting"><label>'+label+(note?'<small>'+note+'</small>':'')+'</label><input aria-label="'+label+'" type="range" data-pref="'+k+'" min="'+min+'" max="'+max+'" step="'+step+'" value="'+prefs[k]+'"><output data-output="'+k+'">'+prefs[k]+suffix+'</output></div>'}
const themeRow=()=>selectRow('Theme','theme',[['graphite','Graphite'],['black','Black']]);
const nightRow=()=>selectRow('Night mode','night',[['off','Off'],['manual','Manual (preview)'],['scheduled','Scheduled (planned)']]);
const brightnessRow=()=>rangeRow('Brightness','brightness',10,100,5,'%','Visual dimming only; not hardware backlight');
const delayRow=()=>selectRow('Auto-hide delay','delay',[[5,'5 seconds'],[10,'10 seconds'],[15,'15 seconds'],[30,'30 seconds'],[60,'60 seconds']]);
function renderQuick(){quick.innerHTML='<header>'+apps[active]+' quick settings<button data-close aria-label="Close quick settings">×</button></header>'+brightnessRow()+nightRow()+themeRow()+delayRow()+(active==='home'||active==='settings'?'':'<p>App-specific controls will be added with the '+apps[active]+' page.</p>')+'<button data-page="settings">All settings</button>'}
function renderSettings(){page.innerHTML='<h1>Settings</h1><div class="settings-layout"><nav class="categories" aria-label="Settings categories">'+[['general','General'],['navigation','Navigation'],['home','Home'],['spotify','Spotify'],['weather','Weather'],['glucose','Glucose'],['connections','Connections'],['system','System']].map(([id,name])=>'<button data-category="'+id+'" class="'+(category===id?'active':'')+'">'+name+'</button>').join('')+'</nav><div class="details" id="settingsDetails"></div></div>';const d=$('settingsDetails');if(category==='navigation'){d.innerHTML='<h2>Navigation</h2>'+delayRow()+selectRow('Rail style','railStyle',[['floating','Floating'],['transparent','Transparent'],['edge','Edge aligned']])+rangeRow('Opacity','opacity',25,100,5,'%')+Object.entries(apps).map(([id,name])=>'<div class="setting"><label for="hide-'+id+'">Auto-hide on '+name+'</label><input id="hide-'+id+'" type="checkbox" data-hide="'+id+'" '+(prefs.autoHide[id]?'checked':'')+'></div>').join('')+'<p>App pinning and ordering are planned.</p>'}else if(category==='general'){d.innerHTML='<h2>General</h2>'+themeRow()+brightnessRow()+nightRow()+selectRow('Animation','animation',[['none','None'],['fade','Fade'],['slide','Slide']])+rangeRow('Animation speed','speed',100,350,50,' ms')+'<p>Startup: Home · Screen: always on (hardware validation pending).</p>'}else{d.innerHTML='<h2>'+({home:'Home',spotify:'Spotify',weather:'Weather',glucose:'Glucose',connections:'Connections',system:'System'}[category])+'</h2><p>Settings for this category will be added in a later increment.</p>'}d.insertAdjacentHTML('beforeend','<button data-reset>Reset preview preferences</button>')}
screen.addEventListener('click',e=>{const b=e.target.closest('button');if(e.target===shade){closeOverlay();return}if(!b)return;if(b.id==='reveal'){setRail(true);return}if(b.id==='quickHandle'){openOverlay('quick');return}if(b.hasAttribute('data-close')){closeOverlay();return}if(b.dataset.open){openOverlay(b.dataset.open);return}if(b.dataset.page){navigate(b.dataset.page);return}if(b.dataset.category){category=b.dataset.category;renderSettings();return}if(b.hasAttribute('data-reset')&&confirm('Reset preview preferences only?')){prefs=defaults();save();renderSettings()}});
screen.addEventListener('input',e=>{const el=e.target,k=el.dataset.pref;if(!k||el.type!=='range')return;prefs[k]=Number(el.value);const o=el.parentElement.querySelector('output');if(o)o.textContent=el.value+(k==='speed'?' ms':'%');save()});
screen.addEventListener('change',e=>{const el=e.target,k=el.dataset.pref;if(el.dataset.hide){prefs.autoHide[el.dataset.hide]=el.checked;save();return}if(k&&el.tagName==='SELECT'){prefs[k]=k==='delay'?Number(el.value):el.value;save()}});
screen.addEventListener('pointerdown',e=>{const r=screen.getBoundingClientRect();gesture={x:e.clientX,y:e.clientY,top:e.clientY-r.top<28,edge:r.right-e.clientX<30,control:!!e.target.closest('input,select,button:not(#quickHandle):not(#reveal)')};schedule()});
screen.addEventListener('pointerup',e=>{if(!gesture)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;const g=gesture;gesture=null;if(overlay||g.control)return;if(g.top&&dy>50&&dy>Math.abs(dx)*1.4)openOverlay('quick');else if(g.edge&&dx< -45&&Math.abs(dx)>Math.abs(dy)*1.4)setRail(true)});
screen.addEventListener('pointercancel',()=>{gesture=null});rail.addEventListener('focusout',()=>setTimeout(schedule,0));screen.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay){closeOverlay();return}schedule()});
apply();renderPage();setRail(true);setInterval(clock,1000);
